SSIRD_PLOT_COLOUR = 'tab:orange'
XPASS_PLOT_COLOUR = 'tab:green'
DCTCP_PLOT_COLOUR = 'tab:blue'

def plot_ssird_flow_latency_cdf(
    experiment_family, title_addendum, experiment_date,
    num_flows_list,
    incast_degree,  # is `n` in `n-to-1` incast; i.e. how many senders are sending to a single receiver
    ssird_srpt_fct_s_list_list,
    ssird_fairshare_fct_s_list_list,
    x_lim=None, y_lim=None
):

    print([len(list) for list in ssird_srpt_fct_s_list_list])
    print([len(list) for list in ssird_fairshare_fct_s_list_list])

    assert(len(set([
        len(ssird_srpt_fct_s_list_list),
        len(ssird_fairshare_fct_s_list_list),
        len(num_flows_list)
    ]))==1)

    num_experiments = len(num_flows_list)
    for i in range(num_experiments):
        assert(num_flows_list[i]*incast_degree == len(ssird_srpt_fct_s_list_list[i]))

    for i in range(num_experiments):
        num_flows_total = num_flows_list[i]*incast_degree

        ssird_srpt_fct_s_list = ssird_srpt_fct_s_list_list[i]
        ssird_srpt_fct_us_list = [round(x*1000*1000) for x in ssird_srpt_fct_s_list]
        ssird_srpt_fct_us_list_sorted = sorted(ssird_srpt_fct_us_list)   

        ssird_fairshare_fct_s_list = ssird_fairshare_fct_s_list_list[i]
        ssird_fairshare_fct_us_list = [round(x*1000*1000) for x in ssird_fairshare_fct_s_list]
        ssird_fairshare_fct_us_list_sorted = sorted(ssird_fairshare_fct_us_list)   

        num_flows_completed_count_cumulative = np.cumsum([1]*num_flows_total).tolist()
        proportion_of_flows_completed = [x / num_flows_total for x in num_flows_completed_count_cumulative]

        plt.figure(figsize=(10, 6))
        plt.xlabel(f'Latency (us)')
        plt.ylabel('Proportion of Flows Completed')
        plt.title(f'Flow Size vs Latency {num_flows_total}flo\n{experiment_family}{title_addendum}\n{experiment_date}')

        plt.plot(ssird_srpt_fct_us_list_sorted, proportion_of_flows_completed, label="SSIRD (SRPT)", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=3, zorder=3)
        plt.plot(ssird_fairshare_fct_us_list_sorted, proportion_of_flows_completed, label="SSIRD (Fair Share)", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=2, zorder=2)

        plt.legend()

        ax = plt.gca()
        ax.grid(True, which='both')

        if (x_lim is not None):
            ax.set_xlim(x_lim)
        if (y_lim is not None):
            ax.set_ylim(y_lim)

        # ax.set_xscale('log')

        Path(PATH_TO_FLOW_LATENCY_CDF).mkdir(parents=True, exist_ok=True)
        filename = f"ssird_flow_latency_cdf_{num_flows_total}flo_{experiment_family}{title_addendum}_{experiment_date}.png"
        plt.savefig(f"{PATH_TO_FLOW_LATENCY_CDF}{filename}")
        plt.close()
        # return

def plot_ssird_flow_latency_cdf_loaded_vs_unloaded(
    experiment_family, title_addendum, experiment_date,
    num_flows_list,
    incast_degree,  # is `n` in `n-to-1` incast; i.e. how many senders are sending to a single receiver
    num_flows_unloaded,
    num_flows_loaded,
    ssird_srpt_fct_s_list_list,
    ssird_fairshare_fct_s_list_list,
    x_lim=None, y_lim=None
):

    print([len(list) for list in ssird_srpt_fct_s_list_list])
    print([len(list) for list in ssird_fairshare_fct_s_list_list])

    assert(len(set([
        len(ssird_srpt_fct_s_list_list),
        len(ssird_fairshare_fct_s_list_list),
        len(num_flows_list)
    ]))==1)

    num_experiments = len(num_flows_list)
    for i in range(num_experiments):
        assert(num_flows_list[i]*incast_degree == len(ssird_srpt_fct_s_list_list[i]))

    plt.figure(figsize=(10, 6))
    plt.xlabel(f'Latency (us)')
    plt.ylabel('Proportion of Flows Completed')
    plt.title(f'Flow Size vs Latency\n{experiment_family}{title_addendum}\n{experiment_date}')

    for i in range(num_experiments):

        num_flows = num_flows_list[i]
        num_flows_total = num_flows*incast_degree

        ssird_srpt_fct_s_list = ssird_srpt_fct_s_list_list[i]
        ssird_srpt_fct_us_list = [round(x*1000*1000) for x in ssird_srpt_fct_s_list]
        ssird_srpt_fct_us_list_sorted = sorted(ssird_srpt_fct_us_list)   

        ssird_fairshare_fct_s_list = ssird_fairshare_fct_s_list_list[i]
        ssird_fairshare_fct_us_list = [round(x*1000*1000) for x in ssird_fairshare_fct_s_list]
        ssird_fairshare_fct_us_list_sorted = sorted(ssird_fairshare_fct_us_list)   

        num_flows_completed_count_cumulative = np.cumsum([1]*num_flows_total).tolist()
        proportion_of_flows_completed = [x / num_flows_total for x in num_flows_completed_count_cumulative]

        if (num_flows == num_flows_unloaded):
            plt.plot(ssird_srpt_fct_us_list_sorted, proportion_of_flows_completed, label="SSIRD-Unloaded)", linestyle='-', marker='o', color=DCTCP_PLOT_COLOUR, markersize=2, zorder=1)
        elif (num_flows == num_flows_loaded):
            plt.plot(ssird_srpt_fct_us_list_sorted, proportion_of_flows_completed, label="SSIRD-Incast (SRPT)", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=3, zorder=3)
            plt.plot(ssird_fairshare_fct_us_list_sorted, proportion_of_flows_completed, label="SSIRD-Incast (Fair Share)", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=2, zorder=2)

    plt.legend()

    ax = plt.gca()
    ax.grid(True, which='both')

    if (x_lim is not None):
        ax.set_xlim(x_lim)
    if (y_lim is not None):
        ax.set_ylim(y_lim)

    # ax.set_xscale('log')

    Path(PATH_TO_FLOW_LATENCY_CDF).mkdir(parents=True, exist_ok=True)
    filename = f"ssird_flow_latency_cdf_loaded_vs_unloaded_{num_flows_total}flo_{experiment_family}{title_addendum}_{experiment_date}.png"
    plt.savefig(f"{PATH_TO_FLOW_LATENCY_CDF}{filename}")
    plt.close()
    # return

